// Generated by scripts/generate-workflow-blueprints.ts (extra questions); edit the specs there and re-run rather than editing by hand.
import { o, s, type QuestionSet } from "@/lib/interview-questions";

const bank: QuestionSet = {
  subjective: [
    s(5, "Walk me through the end-to-end architecture of this metrics, logs and alerting platform.", "Agents on every node scrape Prometheus endpoints and tail container logs. They attach cluster, namespace and service labels, and buffer to local disk if the pipeline is down. They publish compressed batches to separate Kafka topics for metrics and logs, so a traffic spike lands in the queue instead of the stores. Metrics ingesters enforce per-tenant limits, replicate writes and hold recent data in memory and a write-ahead log. Compactors then move blocks to object storage and build downsampled rollups. The log pipeline parses fields, redacts secrets and writes compressed chunks with a small label index. Rulers evaluate recording and alert rules. Alertmanager groups, deduplicates, silences and routes alerts to on-call schedules. Grafana ties dashboards and logs together for whoever gets paged."),
    s(5, "How do you monitor the monitoring platform itself, so you know when it is broken?", "I run meta-monitoring on a separate, minimal stack, ideally in another region or account, so it does not share failure modes with the main platform. It watches ingestion rate, Kafka consumer lag, ingester health, rule evaluation failures and missed iterations, and Alertmanager notification failures. I also use a dead man's switch: an always-firing Watchdog alert sent to an external service. If that heartbeat stops arriving, the external service pages us, because silence means the alert path is broken. I add end-to-end synthetic probes too. A canary writes a known metric and log line, and a checker confirms both are queryable within a freshness target. That catches cases where every component looks healthy but data is not actually flowing."),
    s(5, "The platform is overloaded during a major incident. What do you shed first, and how do you protect the critical signals?", "Load usually peaks exactly when production is broken, so I design shedding to follow priority. Alert-relevant data gets protected capacity: a separate high-priority Kafka topic or quota for metrics that SLO and alert rules use, and dedicated ruler and Alertmanager resources. I shed in this order: expensive ad-hoc queries and long-range dashboards, then debug-level logs, then low-priority tenants' excess series. Every drop increments a visible counter per tenant and reason, so nothing is lost silently. Query concurrency limits and timeouts stop one heavy dashboard from starving the rule evaluator. Agents keep buffering to disk, so delayed data still arrives later. The aim is to degrade exploration first and keep detection and paging working."),
    s(4, "How would you size local disk buffering on the agents, and what happens when it fills up?", "I size the buffer to cover the longest pipeline outage I want to survive without loss, for example an hour. The rough formula is node ingest rate times outage duration, compressed, plus headroom, and I check it against node disk quotas. The buffer must be bounded so it can never fill the node disk and hurt the workload. When it fills, the agent drops with a policy: oldest or lowest-priority data first, debug logs before error logs, never silently. It exposes buffer usage and dropped-bytes metrics. Meta-monitoring alerts when buffers keep growing across many nodes, because that means the pipeline, not one node, is down. On recovery, replay is rate-limited so a thousand agents do not flood Kafka at once."),
    s(5, "Give me a back-of-the-envelope capacity estimate for the metrics side.", "I state assumptions first. Say 10 million active series scraped every 15 seconds. That is about 667,000 samples per second. Prometheus-style compression stores roughly 1 to 2 bytes per sample, so raw data is around 1.3 MB per second at most, about 115 GB a day before replication. With replication factor 3 in ingesters, hot storage triples, though object storage blocks are deduplicated after compaction. Memory usually dominates: each active series in the head block carries labels and chunk overhead, so active series count, not sample rate, drives ingester sizing. Then I add Kafka retention for a few hours of replay, plus query capacity. Finally I plan headroom for spikes and for losing one zone."),
    s(4, "Why index only labels for logs instead of full-text indexing every field, and when would that be the wrong choice?", "A full-text index can be as big as the data and costs a lot of CPU at write time. Most log queries start from a known service, namespace or time range anyway. With a small label index, I store compressed chunks cheaply in object storage and filter them with brute-force parallel scans at query time. Ingest becomes cheap and retention affordable. The trade-off is slower needle-in-haystack searches across huge time ranges, and labels must stay low-cardinality, so no request IDs as labels. It is the wrong choice when users mainly run arbitrary full-text search across everything, like security analytics or audit investigations. In those cases a search engine such as Elasticsearch or OpenSearch, or a columnar store, fits better."),
    s(5, "How do you prevent secrets and personal data from ending up in your log store?", "Defence in depth, as early as possible. First, application logging libraries and code review discourage logging tokens, passwords or personal data. Second, agents or the first pipeline stage run redaction: known secret patterns such as API keys, bearer tokens and card numbers, plus field-based rules that mask fields like email or phone. Redaction happens before data touches Kafka retention or storage, because deleting it later is hard. Third, access is restricted by tenant and team with audit logging. I also limit retention for logs that may contain personal data, which matters for obligations like India's DPDP Act. Finally, I sample stored logs for leaks and treat any leak as an incident: rotate the secret, then purge the affected chunks."),
    s(4, "How do you isolate tenants so one noisy team cannot hurt everyone else?", "Isolation sits at every layer. At ingest, per-tenant limits cover samples per second, active series, labels per series, label value length and log bytes per second, with clear rejection counters. In Kafka, partitioning by tenant and series hash stops one tenant pinning a single partition, and big tenants get more partitions or shuffle sharding across ingesters. On the query path, per-tenant concurrency, series-fetched and bytes-scanned limits apply, plus fair queuing in the query frontend. Rulers can be sharded so one tenant's heavy rules do not delay another's evaluations. Tenant identity comes from authentication, not a client-supplied header. Each tenant gets a usage dashboard, so teams see their own cost and limits before they hit them."),
    s(4, "How does write replication in the ingesters work, and what consistency do queries get?", "Each series hashes onto a ring, and the write goes to several ingesters, typically three. It succeeds when a quorum, two of three, acknowledges. A single ingester failure then loses no acknowledged data, and writes continue. Queries fan out to the replicas and merge the results, deduplicating identical samples. So the recent window is effectively read with quorum semantics: you see acknowledged data even if one replica is behind. Consistency is eventual at the edges. Data still in agent buffers or Kafka is not visible yet, so I track ingestion delay and expose freshness. After compaction, object storage blocks from the replicas are merged and deduplicated, which cuts long-term storage back to one copy."),
    s(4, "Teams run Prometheus in HA pairs that both remote-write. How do you avoid storing double data?", "Each replica adds external labels for cluster and replica. The distributor runs HA deduplication: for each cluster it elects one replica as leader and accepts only that replica's samples, dropping the other's. If the leader stops sending for longer than a failover timeout, the distributor switches to the other replica. A short gap or overlap can occur at failover, which is acceptable for monitoring. The replica label is stripped before storage so series identities match. Without this, you double storage and active series, and sum queries double count. The same problem appears for alerts: both replicas fire identical alerts, which is why Alertmanager dedupes by label set."),
    s(4, "How does a query spanning the last 30 days read from both hot and cold storage?", "A query frontend splits the range into smaller intervals, often by day, checks a results cache and runs the pieces in parallel. Each querier fetches recent data from ingesters and older data from store gateways, which read block indexes and chunks from object storage and cache index headers locally. Results are merged and deduplicated where the windows overlap. For long ranges the querier can pick downsampled blocks based on the step, so a 30-day graph with a one-hour step reads 1-hour rollups instead of raw samples. Limits on series and bytes fetched protect the system. Caching index lookups, chunks and query results matters most, because object storage latency is high."),
    s(4, "What are the pitfalls of downsampling, and how do you keep rollups correct?", "A single average per window destroys information. You lose spikes, and you cannot correctly compute rates or re-aggregate. So each rollup stores several aggregates: count, sum, min and max, plus counter-aware values so rate() still works across resets. Queries then choose the right aggregate, for example max for latency peaks. Histograms must keep bucket counts, not precomputed percentiles, because percentiles cannot be averaged. Users should know a 1-hour rollup cannot show a two-minute outage, so dashboards auto-select resolution based on step. Downsampling saves query time more than storage. I keep raw data long enough for incident reviews, then expire it per tenant policy."),
    s(5, "Explain multi-window, multi-burn-rate SLO alerts and why they beat a raw error-rate threshold.", "Burn rate is how fast you consume the error budget compared with spending it evenly over the SLO window. A burn rate of 1 uses the whole budget exactly over the window. A fast-burn alert pages at a high burn rate measured over a long window, such as one hour, and also requires a short window, such as five minutes, to agree. That combination catches serious incidents quickly and resolves soon after recovery. A slow-burn alert uses a lower burn rate over hours and creates a ticket instead of a page. A raw threshold like 'errors above 1 percent' ignores traffic volume and budget context. It is either noisy or too late. Burn-rate alerts tie paging directly to user impact."),
    s(4, "What are the trade-offs when choosing 'for' durations and evaluation intervals?", "The 'for' duration keeps an alert pending until the condition has held across evaluations for that long. That filters brief blips but adds detection delay. Five minutes of 'for' means at least five minutes before anyone is paged. Evaluation interval sets resolution: a 1-minute interval with a 15-second scrape can miss short spikes between evaluations. Very short intervals cost ruler CPU and load the query path. For critical user-facing SLOs I keep 'for' short and rely on burn-rate windows for smoothing. For noisy infrastructure signals I use longer 'for' or keep_firing_for to avoid flapping. If the condition flickers, the pending timer resets, so I smooth with range functions rather than stretching 'for'."),
    s(4, "How do you alert on missing data, when the metric that would show the problem simply stops arriving?", "Threshold alerts fail silently when the series disappears, because there is nothing to compare. So I add explicit absence checks. absent() or absent_over_time() covers critical series, and up == 0 or missing targets covers scrapes. Freshness alerts track ingestion delay per tenant. For pipelines I alert when Kafka consumer lag grows or when agents report rising buffer usage. I also use synthetic canaries that write known data and verify it end to end. Alerts should be written so 'no data' reads as a problem, not as 'all fine'. In Grafana-managed alerts, that means setting the no-data state deliberately instead of leaving the default."),
    s(4, "How do you make the rule evaluator highly available without causing duplicate pages?", "I run rulers as a sharded group. Each rule group is assigned to an owner through a hash ring, and replicas can take over if the owner fails. Some setups run two evaluators per group on purpose and rely on Alertmanager to deduplicate, since identical label sets collapse into one alert. I monitor missed and slow evaluations, because a ruler that falls behind is effectively blind. Rulers query ingesters and storage directly, with reserved query capacity, so a dashboard storm cannot starve them. On failover, alert state such as pending timers may reset unless state is restored from the ALERTS_FOR_STATE series. That is why Prometheus persists it."),
    s(4, "How does Alertmanager stay highly available, and what delivery guarantee does it give?", "Alertmanager runs as a cluster of usually three replicas that gossip silences and notification logs. Rulers send every alert to all replicas. Each replica waits a position-based delay before sending, and checks the shared notification log first, so normally only one notification goes out. The guarantee is at-least-once, not exactly-once. During a network partition, two replicas may both notify. That is the right bias, because a duplicate page is far better than a missed one. Receivers such as paging tools should deduplicate on a stable key, like the group key. I also monitor failed notifications per integration and keep a secondary channel for the case where the primary paging provider is down."),
    s(3, "What if the external paging provider has an outage during a real incident?", "I treat the paging provider as a dependency with its own failure mode. Alertmanager metrics for failed notifications per receiver trigger an alert that goes through a different channel, such as a second provider, SMS gateway or chat. Critical routes can fan out to two receivers at the same time, and the receivers dedupe. The dead man's switch heartbeat also detects paging-path failure from the outside. Escalation policies make sure an unacknowledged page reaches a secondary on-call. Teams keep a documented manual fallback, such as a status channel and phone tree, which is tested in game days. Notifications retry with backoff, so alerts queue rather than vanish."),
    s(3, "Kafka consumers are falling behind. How do you detect it and recover?", "I track consumer lag per partition, both in messages and in time. Time lag matters more because it shows how stale dashboards and alerts are. Alerting on lag time, not just message count, tells me when detection is degraded. To recover, I scale ingesters or consumers, keeping partition count at least equal to consumer parallelism, and check whether one hot partition is the bottleneck. If lag is beyond Kafka retention, data is lost, so retention must exceed the worst expected outage. During catch-up, ingesters must accept older samples. That requires an out-of-order window, or prioritising the newest data for alerting and backfilling the rest. Rules should flag low data freshness to on-call rather than fire false 'all clear' results."),
    s(3, "Pull or push for metrics collection: what would you choose here, and why?", "I use pull at the node level: agents scrape local Prometheus endpoints. Then I push from agents into Kafka. Pull gives health for free through the up metric, lets operators control scrape rate, and makes it easy to curl a target to debug. Push from agents to the central pipeline works better across clusters and networks, avoids central scrapers reaching into every cluster, and suits the buffering and batching that Kafka needs. For short-lived batch jobs that end before a scrape, I use push through something like a Pushgateway or OTLP. OpenTelemetry collectors support both models, which helps standardise. Mostly it is a hybrid design with clear ownership."),
    s(4, "A team accidentally ships debug logging and log volume jumps tenfold. What does the platform do?", "Per-tenant and per-stream ingestion rate limits kick in at the agent or distributor. Excess lines are rejected or sampled, and each drop is counted by tenant and reason. Kafka absorbs the short-term surge, so other tenants are unaffected. I give priority to error and warn levels over debug, so the useful signal survives. The tenant gets an automatic notification with a usage dashboard showing what is being dropped. Agents can apply dynamic sampling or filter rules pushed from central config without a redeploy. Longer term, cost attribution per team and log-level defaults in libraries prevent repeats. The key point is that the platform degrades that one tenant visibly, not everyone silently."),
    s(3, "How do you correlate metrics, logs and traces so the on-call engineer gets to root cause quickly?", "Correlation depends on consistent identity. Agents attach the same resource labels, cluster, namespace, service and pod, to metrics, logs and traces, ideally following OpenTelemetry semantic conventions. Grafana can then jump from a panel to logs filtered by the same labels and time range. Exemplars attach trace IDs to histogram samples, so a latency spike links straight to example traces. Logs include trace IDs as a parsed field, not a label, to avoid cardinality issues. Every alert carries links to its runbook, dashboard and a pre-filtered logs query, so the engineer does not start from a blank screen. Time synchronisation across nodes also matters, because skew breaks correlation."),
    s(3, "How do retention tiers and data deletion work per tenant, including compliance deletes?", "Each tenant has a policy: how long raw data stays hot, how long downsampled blocks stay in object storage, and when everything expires. Compactors enforce expiry by deleting whole blocks past the window, which is cheap because blocks are time-partitioned. Log chunks expire through object storage lifecycle rules or the compactor. Targeted deletes, such as purging logs that leaked personal data, are harder. I support delete requests that mark series or streams through tombstones, filter them at query time, and rewrite the affected blocks during compaction. Deletion takes time, so I document the SLA. Kafka retention, caches and backups also need bounded lifetimes, or deleted data lingers somewhere."),
    s(4, "How do you secure the ingestion and query paths?", "Agents authenticate with mTLS or short-lived tokens tied to workload identity. The gateway derives the tenant from that identity and ignores any client-claimed tenant header, which prevents writing into or reading another tenant's data. All traffic is encrypted in transit. Kafka uses ACLs per topic, and object storage is encrypted at rest with scoped access for platform services only. On the query side, SSO with RBAC maps users and teams to tenants, with audit logs of who queried what, especially for logs. Alert webhooks and notification secrets are kept in a secret manager. Rate limits protect against abusive or runaway queries. I also treat the observability store as sensitive, because logs often contain more than people intend."),
    s(3, "How do you roll out ingester upgrades without losing data?", "Ingesters hold recent samples in memory, so restarts need care. Every write goes to a write-ahead log on persistent disk first, so a restarted ingester replays it and recovers. With replication factor 3 and quorum writes, restarting one ingester at a time keeps writes succeeding. I roll one zone at a time with zone-aware replication and wait for each ingester to become ready, WAL replayed and back in the ring, before moving on. Kafka helps further: if ingesters consume from Kafka, they can resume from committed offsets after restart. I watch ingestion errors, ring health and query errors during rollout, and stop automatically if they rise."),
    s(3, "How do you test and govern alert rules so they stay useful?", "Alert rules live in version control and go through review, like code. CI runs syntax checks and unit tests, for example promtool test rules, with synthetic series to confirm an alert fires and resolves as expected. Every paging rule must have an owner team label, a severity, a runbook link and a summary that says what is broken for users. Rules are deployed per tenant through an API, not edited by hand in production. I backtest new rules against historical data to estimate how often they would have fired. Rules that never fire or always fire are reviewed regularly. Game days inject failures to prove the important alerts actually page."),
    s(3, "How do you measure whether alerting is healthy rather than noisy?", "I track pages per on-call shift, the share of pages that were actionable, time to acknowledge, time to resolve, and how often alerts flap or auto-resolve before anyone acts. I also track incidents that were found by customers or humans instead of alerts, which counts as a missed detection. Each page gets a quick post-shift label: actionable, noise or duplicate. That data drives tuning: delete, demote to ticket, adjust 'for', or convert to burn-rate. Grouping effectiveness shows whether one incident caused one notification or fifty. Alert quality should be reviewed like reliability, with clear owners, because alert fatigue directly causes missed real incidents."),
    s(3, "How would you design this platform for multi-region operation and disaster recovery?", "I keep ingestion regional. Agents write to the nearest region's Kafka and storage, so a cross-region link failure does not blind a region, and data residency rules can be honoured. Each region runs its own rulers and Alertmanager for local alerts, so paging keeps working if another region fails. Global views come from a query layer that fans out across regions, accepting partial results with a clear warning. Object storage can be replicated cross-region for durability of long-term blocks. Meta-monitoring for each region runs from a different region. I define RPO and RTO for the platform explicitly and test region failover, including where on-call notifications come from."),
    s(3, "Is ingestion at-least-once or exactly-once, and how do you handle duplicates?", "End to end it is at-least-once. Agents retry on failure, Kafka producers may resend, and consumers may reprocess after a rebalance, so duplicates happen. For metrics this is mostly harmless. A sample is identified by series and timestamp, so the TSDB deduplicates identical samples and rejects conflicting duplicates. Replicated writes and HA pairs are deduplicated at query or compaction time. For logs, duplicate lines are possible. Some stores drop exact duplicates within a stream, and otherwise I accept rare duplicates. Idempotent Kafka producers reduce resends. Exactly-once across agents, Kafka and stores is expensive and unnecessary here. Losing data is the real risk, so I bias toward retries and visible drop counters."),
    s(3, "How would you enforce label conventions across hundreds of teams?", "Standardise the resource labels centrally. The agent attaches cluster, namespace and service, so teams cannot omit or misspell them. I publish a naming guide: base units in metric names, _total for counters, and no unbounded values like user IDs, emails or full URLs as labels. Relabel rules at the agent drop or rewrite known-bad labels. Per-tenant limits on labels per series and label value length catch the rest. A cardinality explorer shows teams their top series and labels. CI linting on instrumentation and dashboards helps too. Golden libraries give teams pre-labelled HTTP and RPC metrics with route templates rather than raw paths, so most teams get it right by default."),
  ],
  objective: [
    o(4, "Prometheus-style TSDBs achieve roughly 1–2 bytes per sample mainly through which technique?", ["Delta-of-delta encoding for timestamps and XOR encoding for float values","Gzip compression of each individual sample","Storing only the average value per minute","Full-text indexing of label values"], 0, "Gorilla-style compression stores timestamp delta-of-deltas and XORs consecutive values. Regular scrape intervals and slowly changing values make both very compact."),
    o(4, "What ordering guarantee does Kafka provide for messages from these agents?", ["Global ordering across all partitions of a topic","Ordering within a single partition only","No ordering guarantees at all","Ordering only within a consumer group across topics"], 1, "Kafka orders messages only within a partition. Partitioning by series hash keeps each series' samples in order."),
    o(5, "What is the purpose of an always-firing 'Watchdog' or dead man's switch alert?", ["To test the paging tool's sound settings","To detect when the alerting pipeline itself stops working, because the heartbeat goes missing","To suppress all other alerts during maintenance","To measure query latency in Grafana"], 1, "An external service expects the heartbeat continuously. If it stops arriving, something in the alert path is broken, and the external service pages."),
    o(5, "An alert rule has 'for: 5m'. What happens when its expression first becomes true?", ["It fires immediately and resolves after 5 minutes","It enters a pending state and fires only if the condition stays true for 5 minutes","It is evaluated only every 5 minutes","It sends a page and repeats it every 5 minutes"], 1, "The alert stays pending until the condition has held continuously across evaluations for the 'for' duration."),
    o(4, "In Alertmanager, what does group_wait control?", ["How long to wait before sending the first notification for a new group, so related alerts can be batched","How often a firing alert is re-sent","How long a silence lasts","The rule evaluation interval"], 0, "group_wait delays the first notification of a new group, so alerts that arrive shortly after can join the same notification."),
    o(3, "Which Alertmanager setting controls how often a notification is re-sent for an unchanged, still-firing group?", ["group_interval","repeat_interval","evaluation_interval","scrape_interval"], 1, "repeat_interval sets the re-notification period for a group whose alerts have not changed. group_interval covers sending when new alerts join an existing group."),
    o(4, "For a 30-day SLO, what does a burn rate of 14.4 sustained for one hour consume?", ["About 2% of the monthly error budget","About 14.4% of the monthly error budget","The entire monthly error budget","About 0.1% of the monthly error budget"], 0, "One hour is 1/720 of 30 days, and 14.4/720 equals 0.02, or 2% of the budget. The Google SRE Workbook uses this as a fast-burn paging threshold."),
    o(4, "Why use rate() on a counter instead of graphing the raw counter value?", ["rate() converts counters into gauges permanently","rate() computes per-second increase and handles counter resets after restarts","Raw counters cannot be stored in a TSDB","rate() removes high-cardinality labels"], 1, "Counters only increase and reset on restart. rate() detects resets and gives a meaningful per-second rate."),
    o(3, "In a label-indexed log store like Loki, what is indexed?", ["Every word in every log line","Only the stream labels, while log content sits in compressed chunks","Nothing at all; every query scans all data","Only timestamps"], 1, "Only stream labels are indexed. Line content is filtered by scanning chunks at query time, which keeps the index small and ingest cheap."),
    o(4, "Which set of aggregates should a downsampled rollup keep so common queries stay correct?", ["Only the average","Only the last value","Count, sum, min and max, plus counter-aware values","Only the median"], 2, "Keeping several aggregates lets queries compute averages, peaks, troughs and rates. A single average loses spikes and breaks rate calculations."),
    o(4, "How should you compute a p99 latency across 50 pods that each expose a histogram?", ["Average each pod's p99","Take the maximum of each pod's p99","Sum bucket rates across pods by le, then apply histogram_quantile","Take the median of each pod's p99"], 2, "Percentiles cannot be averaged. Aggregating bucket counts first and then computing the quantile gives a correct estimate."),
    o(3, "In Cortex or Mimir, how are samples from an HA pair of Prometheus servers deduplicated at ingest?", ["By comparing every sample value","By electing one replica per cluster, using cluster and replica labels, and accepting only its samples","By dropping every other sample","By using Kafka exactly-once transactions"], 1, "The distributor tracks a leader replica per cluster label and drops samples from the other replica until failover."),
    o(4, "With replication factor 3 and quorum writes, how many ingesters must acknowledge a write?", ["1","2","3","All ingesters in the ring"], 1, "A quorum of 3 is 2, so a write survives one ingester failure and still succeeds."),
    o(4, "What is the main purpose of an ingester's write-ahead log (WAL)?", ["To speed up long-range queries","To recover in-memory samples after a crash or restart","To store downsampled rollups","To index log lines"], 1, "The WAL persists incoming writes to disk, so the in-memory head block can be rebuilt on restart without losing data."),
    o(4, "Why use recording rules?", ["To precompute expensive or frequently used expressions into new series for fast dashboards and alerts","To record user sessions in Grafana","To log every query for auditing","To silence noisy alerts"], 0, "Recording rules evaluate queries on a schedule and store the results as new series. This makes dashboards and alert rules cheaper and more consistent."),
    o(4, "How is a silence different from an inhibition in Alertmanager?", ["A silence is a time-bound, manually created mute matching labels; an inhibition mutes alerts automatically when a matching source alert is firing","They are identical features","A silence deletes alerts from the ruler","An inhibition only applies to log alerts"], 0, "Silences are explicit and expire, which suits maintenance windows. Inhibitions are rule-based and depend on another alert currently firing."),
    o(4, "An agent's bounded disk buffer is full during a long pipeline outage. What is the best behaviour?", ["Keep writing until the node disk is full","Drop lowest-priority data first and expose dropped-data counters","Crash the agent so Kubernetes restarts it","Silently discard all new data"], 1, "The buffer must never harm the workload. Prioritised dropping keeps the most important data, and counters make the loss visible."),
    o(3, "What is one advantage of pull-based scraping?", ["It works best for jobs that finish in under a second","The scraper generates an 'up' metric, so a down target is detected automatically","It needs no service discovery","It removes the need for labels"], 1, "A failed scrape sets up to 0. That is an immediate health signal which push models must build separately."),
    o(3, "What is the appropriate way to get metrics from a short-lived batch job that finishes before a scrape?", ["Increase the scrape interval","Push them through a Pushgateway or an OTLP push","Ignore batch jobs","Write them into log lines only"], 1, "Short-lived jobs may never be scraped. Pushing their final metrics to an intermediary or collector makes them observable."),
    o(4, "Which PromQL function helps alert when a critical series stops reporting entirely?", ["rate()","absent() or absent_over_time()","topk()","increase()"], 1, "absent() returns a result when no matching series exists. A threshold rule on missing data would otherwise never fire."),
    o(4, "Kafka consumer lag measured in time is growing for the metrics topic. What does it most directly mean?", ["Dashboards and alerts are evaluating stale data","Agents are dropping data","Storage is out of space","Alertmanager is down"], 0, "Lag means ingesters have not consumed recent data yet. Queries and rules see an older picture, so detection is delayed."),
    o(4, "Where should secrets and personal data ideally be redacted from logs?", ["In Grafana when displaying results","As early as possible, at the agent or first pipeline stage before durable storage","During monthly compaction","Never; access control is enough"], 1, "Early redaction stops sensitive data from spreading into Kafka retention, caches, storage and backups, where removing it is hard."),
    o(4, "How should the platform determine an incoming write's tenant ID?", ["From a header the client sets freely","From the authenticated identity, such as an mTLS certificate or token, enforced at the gateway","From the metric name prefix","Randomly, for load balancing"], 1, "Deriving the tenant from authenticated identity prevents a client from writing into or reading another tenant's data."),
    o(3, "What do exemplars provide in this platform?", ["Example alert rules","Trace IDs attached to specific metric samples, linking metrics to traces","Sample dashboards for new tenants","Compressed log chunks"], 1, "Exemplars attach a trace reference to a sample, such as a histogram bucket, so you can jump from a latency spike to a matching trace."),
    o(3, "Why store compacted TSDB blocks in object storage?", ["It has the lowest read latency","It is durable, scalable and cheap per GB for large volumes of immutable data","It supports in-place sample updates","It removes the need for indexes"], 1, "Immutable blocks suit object storage's cheap, durable capacity. Caches and store gateways hide its higher latency."),
    o(5, "A metric has labels method (3 values), status (5 values) and pod (100 values). What is the maximum number of series?", ["108","500","1,500","300"], 2, "Series count is the product of label value combinations: 3 × 5 × 100 = 1,500."),
    o(4, "One million active series are scraped every 15 seconds. Roughly how many samples per second is that?", ["About 15,000","About 66,700","About 1,000,000","About 15,000,000"], 1, "Each series yields one sample every 15 seconds, so 1,000,000 ÷ 15 ≈ 66,667 samples per second."),
    o(3, "What delivery semantics does an HA Alertmanager cluster provide for notifications?", ["Exactly-once","At-most-once","At-least-once, so receivers should deduplicate","Best-effort with no retries"], 2, "Replicas coordinate through gossip but can both send during partitions. The system deliberately prefers a duplicate page over a missed one."),
    o(4, "Partitioning the metrics topic only by tenant ID most likely causes which problem?", ["Lost ordering within a series","A hot partition when one large tenant sends most of the traffic","Duplicate alerts","Data being encrypted twice"], 1, "All of a big tenant's data lands on one partition and one consumer. Adding series hash spreads that load."),
    o(4, "Which alert is most appropriate to page an on-call engineer at night?", ["A node's CPU is above 80% for one minute","The checkout SLO error budget is burning at a high rate over both 1h and 5m windows","A disk will be full in 30 days","A deployment finished successfully"], 1, "Pages should be for urgent, user-impacting symptoms. A fast multi-window burn rate on a key SLO is both."),
  ],
};
export default bank;
